<div class="article-editor" data-article-editor>
  <div class="editor-toolbar" role="toolbar" aria-label="Format artikel">
    <select class="editor-format" aria-label="Format paragraf"><option value="p">Paragraf</option><option value="h2">Judul Bagian</option><option value="h3">Subjudul</option><option value="blockquote">Kutipan</option></select>
    <span class="editor-separator"></span>
    <button type="button" data-command="bold" title="Tebal"><strong>B</strong></button><button type="button" data-command="italic" title="Miring"><em>I</em></button><button type="button" data-command="underline" title="Garis bawah"><u>U</u></button>
    <span class="editor-separator"></span>
    <button type="button" data-command="justifyLeft" title="Rata kiri">≡</button><button type="button" data-command="justifyCenter" title="Rata tengah">≡</button><button type="button" data-command="justifyRight" title="Rata kanan">≡</button><button type="button" data-command="justifyFull" title="Rata kanan-kiri">☰</button>
    <span class="editor-separator"></span>
    <button type="button" data-command="insertUnorderedList" title="Bullet">• List</button><button type="button" data-command="insertOrderedList" title="Penomoran">1. List</button><button type="button" data-command="createLink" title="Sisipkan tautan">Link</button>
    <span class="editor-separator"></span>
    <button type="button" data-command="undo" title="Urungkan">↶</button><button type="button" data-command="redo" title="Ulangi">↷</button><button type="button" data-command="removeFormat" title="Hapus format">Tx</button>
  </div>
  <div class="editor-surface" contenteditable="true" role="textbox" aria-multiline="true" data-placeholder="Tulis konten artikel di sini..."></div>
</div>
